def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    unprovoked = 0
    unprovoked5 = 0
    opp_d5 = 0
    opp_d10 = 0

    last5 = n - 5
    if last5 < 0:
        last5 = 0
    last10 = n - 10
    if last10 < 0:
        last10 = 0

    for i, pair in enumerate(history):
        m = pair[0]
        o = pair[1]
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
            if i >= last5:
                opp_d5 += 1
            if i >= last10:
                opp_d10 += 1
            if i == 0 or history[i - 1][0] == 'C':
                unprovoked += 1
                if i >= last5:
                    unprovoked5 += 1

    opp_rate = opp_d / n

    opp_def_streak = 0
    for pair in reversed(history):
        if pair[1] == 'D':
            opp_def_streak += 1
        else:
            break

    my_def_streak = 0
    for pair in reversed(history):
        if pair[0] == 'D':
            my_def_streak += 1
        else:
            break

    before_len = n
    while before_len > 0 and history[before_len - 1][0] == 'D':
        before_len -= 1

    opp_c_before = 0
    for i in range(before_len):
        if history[i][1] == 'C':
            opp_c_before += 1

    was_pre_coop = before_len >= 8 and opp_c_before * 10 >= before_len * 7

    my_last, op_last = history[-1]

    very_nasty = (opp_rate >= 0.42 or opp_d5 >= 4 or opp_d10 >= 6 or
                  unprovoked >= 5 or opp_def_streak >= 6)

    if very_nasty:
        provoked_now = (op_last == 'D' and my_last == 'C' and n >= 2 and
                        history[-2][0] == 'D' and opp_def_streak <= 5)
        if not (was_pre_coop and unprovoked <= 4 and
                (my_def_streak >= 5 or provoked_now)):
            return 'D'

    if op_last == 'D':
        if my_last == 'D':
            if unprovoked5 >= 2 or unprovoked >= 5:
                return 'D'
            if was_pre_coop:
                return 'C'
            if opp_rate < 0.35 and unprovoked <= 4:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if was_pre_coop and unprovoked <= 4 and unprovoked5 <= 1 and opp_def_streak <= 5:
                return 'C'

        if n >= 90 and (unprovoked >= 2 or opp_def_streak >= 2):
            return 'D'

        if (opp_def_streak <= 4 and unprovoked <= 4 and unprovoked5 <= 1 and
                opp_rate < 0.35 and opp_d <= max(5, n // 5)):
            return 'C'

        return 'D'

    if my_last == 'D':
        if opp_rate < 0.40 or (was_pre_coop and unprovoked <= 4):
            if unprovoked <= 5 and my_def_streak < 80:
                return 'D'
        return 'C'

    if (opp_rate >= 0.35 or unprovoked >= 5 or unprovoked5 >= 2 or
            opp_d5 >= 3 or opp_d10 >= 5):
        if not (was_pre_coop and unprovoked <= 4 and my_d > 0):
            return 'D'

    if n == 25 or n == 45 or n == 65:
        if my_d == 0 and opp_def_streak == 0 and opp_d5 <= 1:
            if unprovoked == 0:
                if n == 25:
                    prob = 0.30
                elif n == 45:
                    prob = 0.20
                else:
                    prob = 0.12
            elif unprovoked <= 4:
                if n == 25:
                    prob = 0.12
                elif n == 45:
                    prob = 0.08
                else:
                    prob = 0.04
            else:
                prob = 0.0

            if prob > 0.0 and rng.random() < prob:
                return 'D'

    return 'C'
